from pathlib import Path
import json,csv
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text());titles=json.loads((P/'titles.json').read_text())
def p(a,k,t):e[f'A{a:04d}-B{k:04d}']=t
p(568,2,'瑞克，又称“恶臭瑞克”，是组成“恶臭瑞克世界织网”的异形种族之一。这个新兴帝国正开始向帝国空域扩张。')
p(568,4,'瑞克曾多次与人类交战，其中包括同阿卡迪乌斯行商浪人王朝成员的冲突。加伦堡之战中，一支瑞克虚空群遭遇该王朝的阿巴德·格里特所率部队。阿巴德独力遏止了异形登陆船源源不断的登陆攻势。')
p(568,6,'瑞克还曾占据钛帝国辖下的西科阿星系。铵瓦到来后，激起火战士的义愤，使他们向憎恨的瑞克发动进攻，最终将其从西科阿消灭。')
p(569,2,'密教由多种古老异形组成，自称与“原初毁灭者”的力量对抗，早在人类演化成形之前便已开始。它们最为人所知的事迹，是介入荷鲁斯之乱：在大背叛发生前，借对荷鲁斯行动的预知，似乎说服了阿尔法瑞斯·欧米伽及其军团，为自己的目标效力。')
p(569,5,'密教汇集了形态各异的物种，多数对帝国而言都难以辨认。其中既有疑似机械生命，也有看起来由能量构成的存在；另一些则近似昆虫、鸟类或蜥蜴。灵族是已明确确认的成员种族之一。组织中还至少有一名人类，不过此人更像听命行事的代理人，而非平等的同僚。')
p(569,7,'密教居无定所，足迹遍布银河，偶尔会在某处停留一段时间。它们在特定星系选取行星作为“驻留点”，改造地形以适应自身需要，并以相同模式建造着陆区。懂得辨认这些地貌特征的人，便能找出它们曾经驻足的世界，例如努尔特与厄奥利斯。除了重塑地貌，密教还精通大气改造，能够延长生命、使生命重获活力。不过，其最主要的能力，是一种强化的预见术，称为“洞察”。')
p(569,8,'The Cabal and the Alpha Legion 密教与阿尔法军团')
p(569,10,'密教后来指使代理人约翰·格拉马迪库斯与达蒙·普莱塔尼斯，携带雷击石前往马库拉格，刺杀沃坎。')
p(569,12,'经过数十年研究原体的成长，密教认定，其中最关键的是“最年长”的荷鲁斯与“最年轻”的阿尔法瑞斯·欧米伽。它们预见，荷鲁斯将借混沌之力点燃席卷银河的内战，并声称，荷鲁斯所做的一切，将由阿尔法瑞斯消解。密教还宣称，叛乱虽无可避免，阿尔法军团却正处于最适合左右战局的位置，可以将其导向两种可能结局中的一种。')
p(569,15,'密教相信，即使赢得战争，荷鲁斯心中仍会残存一丝昔日的高尚。这点良知将不断折磨他，激起足以自毁的憎恨与厌恶，促使他转而攻击自己的臣属，让叛乱的暴力愈演愈烈。叛军与混沌势力将陷入内斗，最终走向毁灭性的末日决战。在荷鲁斯统治下，人类将在两三代之内彻底灭绝；而与人类纠缠极深的混沌力量，也将随之熄灭。')
p(569,18,'在另一种预见中，帝皇以自己的生命为代价杀死荷鲁斯，化作一个面容僵扭、永远哀号的存在，被困于黄金王座。密教认为，这条道路将使帝国陷入停滞，继而衰败；衰败又会不断加速，让混沌力量日益壮大、影响蔓延。经历一万或两万年的苦难后，整个银河终将被混沌吞噬。')
p(569,21,'密教着眼于漫长的未来，试图让阿尔法瑞斯·欧米伽相信预言，促成第一种结局。它们要求这位原体违背对帝皇的誓言，率军投向荷鲁斯，竭尽全力确保背叛者取胜，以牺牲人类为代价毁灭混沌。现有记载似乎表明，阿尔法军团原体接受了请求。然而，叛乱最终却以第二种方式结束，密教的谋划显然失败；若其预言可信，银河便注定走向灭亡。阿尔法军团仍被视为帝国与帝皇的叛徒，但自接触密教以来，它们的真实动机与效忠对象，始终成谜。')
p(569,23,'密教曾继续设法左右叛乱的结局，包括派出携带雷击石的约翰·格拉马迪库斯，试图杀死沃坎原体。它们相信，混沌赢得战争最终会使人类灭绝，从而大幅削弱混沌诸神赖以汲取力量的情感来源。')
p(569,26,'乌斯维的大先知艾尔德拉德·乌瑟兰最终认定，密教已成为银河的威胁。它们想用灭绝人类的方式杀死混沌诸神，在他看来，不过是一场毫无希望的仪式献祭。艾尔德拉德在“洞察”所示的结局之外，看到了另一条道路：帮助沃坎抵达泰拉等行动，可以促成帝国获胜。然而，密教仍执意坚持原有计划，于是艾尔德拉德招募怀言者巴图萨·纳瑞克，着手清除其成员。两人杀死了密教的大多数首领与代理人，包括加赫特、斯劳·达、卡图尔·乌梅尼德斯，以及达蒙·普莱塔尼斯。')
p(569,28,'M32，艾尔德拉德·乌瑟兰表示，密教已经不复存在，其击败混沌的计划也已失败。')
p(569,33,"G'Lattro 格拉特罗")
p(569,39,'达蒙·普莱塔尼斯——人类永生者')
p(569,41,'昔兰尼·瓦兰蒂恩——人类永生者')
p(570,2,'乌卢梅亚蒂人是组成乌卢梅亚蒂克联盟的异形种族之一。这个新兴帝国在遭遇泰伦之前，已经开始侵占帝国空域。')
p(570,5,'娜迦虫巢舰队重创了乌卢梅亚蒂克联盟。801.M41，入侵开始后仅数日，外围殖民地便遭吞噬；基因窃取者还藏入逃难船只，继而侵染瓦里安太空船坞。809.M41，联盟的王座世界也被泰伦吞没，剩余世界随即宣布隔离。所幸，玛兰泰、伊扬登与伊德哈尔方舟世界的灵族军队，终于在812.M41摧毁了这支虫巢舰队。联盟损失如此惨重，几乎不可能再构成入侵前那样的威胁。到了第41千年末，人类似乎已认为，它们的文明基本遭到毁灭。')
p(570,8,'联盟拥有一种能量约束技术，与混沌屠戮者所用灵魂燃烧炮的技术相似；但二者是否有关联，无法证实。')
titles.update({'568':'恶臭瑞克 Noisome Reek','569':'密教 The Cabal'})
n.update({'A0568-B0002':'Noisome Reek 沿18核心恶臭瑞克；本篇原音译诺伊瑟姆·瑞克保留原篇名。Worldweave 为政体名称，暂定世界织网，不误读为编织者个人。','A0568-B0004':'interface vessels 按往返太空与地面的登陆船理解；made planetfall 是登陆，不是坠毁。','A0568-B0006':'Aun’Va 暂沿原稿铵瓦并规范撇号；官网检索仅找到英文名，未将其认证为官译。Fire Warriors 为火战士泛称，非特定 Strike/Breacher 小队名。','A0569-B0002':'Cabal 沿22与561统一密教，原密会为同一组织别名。各项未来结局均为密教的预言主张，不当作全知叙述。','A0569-B0007':'Acuity 按本篇预见能力暂定洞察，原敏锐不作普通性格形容词；halting-sites 为驻留点，不是时间停滞区域。','A0569-B0012':'最年长与最年轻为本篇密教称谓，保留引号，不据此断言生理年龄或完整发现顺序。','A0569-B0015':'fall on his subjects 为攻击自己的臣属，原译荷鲁斯倒下导致剧情主体错误。','A0569-B0023':'此段叙述回到叛乱期间，与前段战争结束总结并非严格时间顺序；保留原编排，改用曾提示。','A0569-B0026':'人物统一官译艾尔德拉德·乌瑟兰；巴图萨·纳瑞克、达蒙·普莱塔尼斯沿既定暂译。未把密教预言当作确定历史。','A0570-B0002':'Uluméathic 为族名或其形容形式，Uluméathi 为同种族变体；统一乌卢梅亚蒂人，联盟全称沿乌卢梅亚蒂克联盟。','A0570-B0008':'英文 energy energy 为重复；containment 指约束、封存能量，二者技术联系仍为未证实猜测。'})
rows=list(csv.DictReader((P/'terms.tsv').open(),delimiter='\t'));cols=list(rows[0]);by={r[cols[0]].casefold():r for r in rows}
for en,zh in [('Noisome Reek','恶臭瑞克'),('Reek','瑞克'),('Worldweave of the Noisome Reek','恶臭瑞克世界织网'),('Arcadius','阿卡迪乌斯'),('Abad Gerrit','阿巴德·格里特'),('Ghallenburg','加伦堡'),("Si’coa",'西科阿'),("Aun’Va",'铵瓦'),('Fire Warriors','火战士'),('Cabal','密教'),('Primordial Annihilator','原初毁灭者'),('Nurth','努尔特'),('Eolith','厄奥利斯'),('Acuity','洞察'),('Gahet','加赫特'),('Slau Dha','斯劳·达'),('Cartur Umenedies','卡图尔·乌梅尼德斯'),("G’Lattro",'格拉特罗'),('Athithirtir','阿提西尔提尔'),('Drahendra','德拉亨德拉'),('Uluméathic League','乌卢梅亚蒂克联盟'),('Naga','娜迦'),('Varryean Space Docks','瓦里安太空船坞'),("Malan’tai",'玛兰泰'),('Iyanden','伊扬登'),('Idharae','伊德哈尔'),('Soulburner Petard','灵魂燃烧炮'),('Chaos Decimator','混沌屠戮者')]:
 by.setdefault(en.casefold(),dict(zip(cols,[en,zh,'暂定·官方待核','所给英文底稿','篇0568—0570','沿已定词或依本篇语义暂译；同名预言、历史与人物身份不混同。'])))
with (P/'terms.tsv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=cols,delimiter='\t');w.writeheader();w.writerows(by.values())
for fn,obj in [('edits.json',e),('notes.json',n),('titles.json',titles)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
rv=set(json.loads((P/'reviewed.json').read_text()))|{568,569,570};(P/'reviewed.json').write_text(json.dumps(sorted(rv)))
print('568-570 complete')
